// src/services/SelectedPaxService.js
import { SITE_ID, getCurrentSheetId } from '../config/siteConfig';

const WEBAPP_URL = process.env.REACT_APP_GAS_WEBAPP_URL;
const SITE_TOKEN = process.env.REACT_APP_SITE_TOKEN || '';

function makeUUID() {
  if (typeof crypto !== 'undefined' && crypto.randomUUID) return crypto.randomUUID();
  return 'uuid-' + Date.now() + '-' + Math.random().toString(16).slice(2);
}

function requireSheetId() {
  const id = getCurrentSheetId();
  if (!id) throw new Error(`Aucun Sheet ID pour le site "${SITE_ID}"`);
  return id;
}

// ---- transport fire-and-forget (pour append/delete)
function postOpaque(bodyObj) {
  const payload = JSON.stringify(bodyObj);

  if (typeof navigator !== 'undefined' && navigator.sendBeacon) {
    try {
      const blob = new Blob([payload], { type: 'text/plain;charset=UTF-8' });
      const ok = navigator.sendBeacon(WEBAPP_URL, blob);
      if (ok) return;
    } catch (_) {}
  }

  try {
    fetch(WEBAPP_URL, { method: 'POST', mode: 'no-cors', body: payload });
  } catch (_) {}
}

// ✅ NOUVEAU: transport visible avec logs pour les updates (debug CORS-friendly)
async function postWithLog(bodyObj, label) {
  const payload = JSON.stringify(bodyObj);
  
  console.log(`📤 [${label}] Envoi:`, bodyObj);

  // Essai 1 : fetch avec redirect:follow (Apps Script redirige vers le résultat)
  try {
    const response = await fetch(WEBAPP_URL, {
      method: 'POST',
      redirect: 'follow',
      body: payload,
      headers: { 'Content-Type': 'text/plain;charset=UTF-8' }
    });
    
    // Tenter de lire la réponse
    try {
      const text = await response.text();
      console.log(`📥 [${label}] Réponse (${response.status}):`, text);
      return JSON.parse(text);
    } catch (e) {
      console.log(`📥 [${label}] Réponse (${response.status}): lecture impossible (CORS)`, e.message);
    }
    
    return { ok: true };
  } catch (err) {
    console.warn(`⚠️ [${label}] fetch échoué:`, err.message, '→ fallback sendBeacon');
    
    // Fallback : sendBeacon (fire-and-forget)
    try {
      const blob = new Blob([payload], { type: 'text/plain;charset=UTF-8' });
      const sent = navigator.sendBeacon(WEBAPP_URL, blob);
      console.log(`📤 [${label}] sendBeacon: ${sent ? 'envoyé' : 'ÉCHEC'}`);
    } catch (e2) {
      console.error(`❌ [${label}] Échec total:`, e2);
    }
    
    return { ok: false, error: err.message };
  }
}

export async function appendSelectedPassenger(passenger) {
  if (!WEBAPP_URL) throw new Error('REACT_APP_GAS_WEBAPP_URL manquant.');
  const sheetId = requireSheetId();
  const uuid = makeUUID();

  const body = {
    action: 'append',
    sheetId,
    siteId: SITE_ID,
    token: SITE_TOKEN,
    passenger: {
      uuid,
      created_at: new Date().toISOString(),
      idPax: passenger.idPax || '',
      lastName: passenger.lastName || '',
      firstName: passenger.firstName || '',
      flightNumber: passenger.flightNumber || '',
      departureTime: passenger.departureTime || '',
      goLieu: passenger.goLieu || '',
      goAcc: passenger.goAcc || '',
      ssr1: passenger.ssr1 || '',
      isSkyPriority: !!passenger.isSkyPriority,
      isAssisted: !!passenger.isAssisted
    }
  };

  // ✅ Utiliser postWithLog pour l'append aussi (debug)
  await postWithLog(body, 'append');
  return { rowNumber: undefined, uuid };
}

export function deleteRowByUuid(uuid) {
  if (!WEBAPP_URL || !uuid) return;
  const sheetId = requireSheetId();
  postOpaque({ action: 'deleteByUuid', sheetId, token: SITE_TOKEN, uuid });
}

export function deleteRowByNumber(rowNumber) {
  if (!WEBAPP_URL || !rowNumber || rowNumber < 2) return;
  const sheetId = requireSheetId();
  postOpaque({ action: 'deleteByRow', sheetId, token: SITE_TOKEN, rowNumber });
}

// ✅ FIX: update avec logs visibles pour diagnostiquer le problème
export async function updateSelectedPassenger(uuid, fields) {
  if (!WEBAPP_URL || !uuid || !fields) {
    console.warn('⚠️ updateSelectedPassenger: paramètres manquants', { WEBAPP_URL: !!WEBAPP_URL, uuid, fields });
    return;
  }
  const sheetId = requireSheetId();
  
  const body = { 
    action: 'updateByUuid', 
    sheetId, 
    token: SITE_TOKEN, 
    uuid, 
    fields 
  };
  
  return postWithLog(body, `update ${Object.keys(fields).join(',')}`);
}