// IPRestriction.js
import React, { useState, useEffect } from 'react';
import styled from 'styled-components';

const BlockedContainer = styled.div`
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  min-height: 100vh;
  background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);
  color: white;
  padding: 2rem;
  text-align: center;
`;

const BlockedCard = styled.div`
  background: white;
  color: #333;
  padding: 3rem;
  border-radius: 12px;
  box-shadow: 0 10px 40px rgba(0, 0, 0, 0.2);
  max-width: 500px;
`;

const BlockedTitle = styled.h1`
  font-size: 2rem;
  margin-bottom: 1rem;
  color: #dc3545;
`;

const BlockedMessage = styled.p`
  font-size: 1.1rem;
  line-height: 1.6;
  margin-bottom: 1.5rem;
`;

const IPAddress = styled.code`
  background: #f8f9fa;
  padding: 0.5rem 1rem;
  border-radius: 4px;
  font-family: 'Courier New', monospace;
  color: #495057;
  display: inline-block;
  margin-top: 0.5rem;
`;

// ✅ Liste des IPs autorisées - À CONFIGURER
const ALLOWED_IPS = process.env.REACT_APP_ALLOWED_IPS;

// ✅ OPTION: Charger depuis .env
// const ALLOWED_IPS = process.env.REACT_APP_ALLOWED_IPS?.split(',') || [];

const IPRestriction = ({ children }) => {
  const [isAllowed, setIsAllowed] = useState(null);
  const [userIP, setUserIP] = useState('');
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    checkIPAccess();
  }, []);

  const checkIPAccess = async () => {
    try {
      const response = await fetch('https://api.ipify.org?format=json');
      const data = await response.json();
      const ip = data.ip;
      
      setUserIP(ip);
      
      console.log('🔍 Vérification IP:', {
        ipUtilisateur: ip,
        ipsAutorisees: ALLOWED_IPS,
        acces: ALLOWED_IPS.includes(ip) ? 'AUTORISÉ' : 'REFUSÉ'
      });
      
      setIsAllowed(ALLOWED_IPS.includes(ip));
      
    } catch (error) {
      console.error('❌ Erreur vérification IP:', error);
      setIsAllowed(false); // Bloquer par défaut en cas d'erreur
    } finally {
      setLoading(false);
    }
  };

  if (loading) {
    return (
      <BlockedContainer>
        <BlockedCard>
          <BlockedMessage>🔒 Vérification de l'accès en cours...</BlockedMessage>
        </BlockedCard>
      </BlockedContainer>
    );
  }

  if (!isAllowed) {
    return (
      <BlockedContainer>
        <BlockedCard>
          <BlockedTitle>🚫 Accès Refusé</BlockedTitle>
          <BlockedMessage>
            Désolé, votre adresse IP n'est pas autorisée à accéder à cette application.
          </BlockedMessage>
          <BlockedMessage>
            Votre IP actuelle :
            <br />
            <IPAddress>{userIP || 'Non détectée'}</IPAddress>
          </BlockedMessage>
          <BlockedMessage style={{ fontSize: '0.9rem', color: '#6c757d', marginTop: '2rem' }}>
            Pour obtenir l'accès, veuillez contacter l'administrateur système.
          </BlockedMessage>
        </BlockedCard>
      </BlockedContainer>
    );
  }

  return <>{children}</>;
};

export default IPRestriction;

