import React, { useState, useEffect, useCallback } from 'react';
import styled, { keyframes } from 'styled-components';
import { fetchSelectedPaxHistory } from '../services/SelectedPaxReader';
import {
  FaChartBar,
  FaUserFriends,
  FaCrown,
  FaCheckCircle,
  FaWheelchair,
  FaPlane,
  FaClock,
  FaWalking,
  FaSyncAlt,
  FaCalendarAlt,
  FaPercentage
} from 'react-icons/fa';
import {
  BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer,
  PieChart, Pie, Cell, Legend,
  LineChart, Line,
  AreaChart, Area
} from 'recharts';

// Animations
const fadeIn = keyframes`
  from { opacity: 0; transform: translateY(15px); }
  to { opacity: 1; transform: translateY(0); }
`;

const pulse = keyframes`
  0% { transform: scale(1); }
  50% { transform: scale(1.03); }
  100% { transform: scale(1); }
`;

// Palette
const PALETTE = {
  primary:    '#0056b3',
  secondary:  '#6c757d',
  success:    '#198754',
  warning:    '#ffc107',
  danger:     '#dc3545',
  info:       '#0dcaf0',
  skyPriority:'#e63946',
  bg:         '#f0f2f5',
  card:       '#ffffff',
  text:       '#212529',
  textLight:  '#6c757d',
  border:     '#dee2e6',
};

const CHART_COLORS = ['#0056b3', '#198754', '#dc3545', '#ffc107', '#6f42c1', '#0dcaf0', '#fd7e14', '#20c997'];
const PIE_COLORS = ['#0056b3', '#ffc107', '#dc3545', '#6c757d', '#198754'];

// Styled Components
const PageContainer = styled.div`
  animation: ${fadeIn} 0.5s ease-out;
  padding: 1.5rem;
  background-color: ${PALETTE.bg};
  min-height: 80vh;
`;

const PageHeader = styled.div`
  display: flex;
  justify-content: space-between;
  align-items: center;
  flex-wrap: wrap;
  gap: 1rem;
  background: linear-gradient(135deg, ${PALETTE.primary} 0%, #004494 100%);
  border-radius: 12px;
  padding: 1.2rem 1.5rem;
  margin-bottom: 1.5rem;
  color: white;
  box-shadow: 0 2px 8px rgba(0,0,0,0.15);
`;

const PageTitle = styled.h1`
  margin: 0;
  font-size: 1.5rem;
  font-weight: 600;
  display: flex;
  align-items: center;
  gap: 0.8rem;
`;

const HeaderActions = styled.div`
  display: flex;
  align-items: center;
  gap: 1rem;
`;

const DateFilter = styled.div`
  display: flex;
  align-items: center;
  gap: 0.5rem;
`;

const DateInput = styled.input`
  padding: 0.4rem 0.6rem;
  border-radius: 6px;
  border: 1px solid rgba(255,255,255,0.3);
  background: rgba(255,255,255,0.15);
  color: white;
  font-size: 0.85rem;
  
  &::-webkit-calendar-picker-indicator { filter: invert(1); }
`;

const RefreshBtn = styled.button`
  display: flex;
  align-items: center;
  gap: 0.5rem;
  background: rgba(255,255,255,0.2);
  color: white;
  border: none;
  border-radius: 8px;
  padding: 0.5rem 1rem;
  font-weight: 600;
  font-size: 0.85rem;
  cursor: pointer;
  transition: all 0.2s;
  &:hover { background: rgba(255,255,255,0.3); }
  &:disabled { opacity: 0.5; cursor: not-allowed; }
`;

// KPI Cards
const KPIGrid = styled.div`
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
  gap: 1rem;
  margin-bottom: 1.5rem;
`;

const KPICard = styled.div`
  background: ${PALETTE.card};
  border-radius: 12px;
  padding: 1.2rem;
  box-shadow: 0 2px 6px rgba(0,0,0,0.06);
  display: flex;
  align-items: center;
  gap: 1rem;
  animation: ${fadeIn} 0.5s ease-out;
  animation-delay: ${props => props.$delay || '0s'};
  animation-fill-mode: backwards;
  border-left: 4px solid ${props => props.$color || PALETTE.primary};
  transition: transform 0.2s;
  &:hover { transform: translateY(-2px); }
`;

const KPIIcon = styled.div`
  width: 48px;
  height: 48px;
  border-radius: 12px;
  display: flex;
  align-items: center;
  justify-content: center;
  background: ${props => props.$bgColor || 'rgba(0,86,179,0.1)'};
  color: ${props => props.$color || PALETTE.primary};
  flex-shrink: 0;
`;

const KPIContent = styled.div`
  display: flex;
  flex-direction: column;
`;

const KPIValue = styled.span`
  font-size: 1.6rem;
  font-weight: 700;
  color: ${PALETTE.text};
  line-height: 1.2;
`;

const KPILabel = styled.span`
  font-size: 0.8rem;
  color: ${PALETTE.textLight};
  font-weight: 500;
`;

// Charts
const ChartsGrid = styled.div`
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(450px, 1fr));
  gap: 1.5rem;
  margin-bottom: 1.5rem;
`;

const ChartCard = styled.div`
  background: ${PALETTE.card};
  border-radius: 12px;
  padding: 1.5rem;
  box-shadow: 0 2px 6px rgba(0,0,0,0.06);
  animation: ${fadeIn} 0.5s ease-out;
`;

const ChartTitle = styled.h3`
  margin: 0 0 1rem 0;
  font-size: 1rem;
  font-weight: 600;
  color: ${PALETTE.text};
  display: flex;
  align-items: center;
  gap: 0.5rem;
`;

// Table
const TableCard = styled(ChartCard)`
  overflow-x: auto;
`;

const StatsTable = styled.table`
  width: 100%;
  border-collapse: collapse;
  font-size: 0.85rem;
  
  th, td {
    padding: 0.6rem 0.8rem;
    text-align: left;
    border-bottom: 1px solid ${PALETTE.border};
  }
  
  th {
    background: ${PALETTE.bg};
    font-weight: 600;
    color: ${PALETTE.text};
    position: sticky;
    top: 0;
  }
  
  tr:hover td { background: rgba(0,86,179,0.04); }
`;

const Badge = styled.span`
  display: inline-block;
  padding: 0.2rem 0.6rem;
  border-radius: 20px;
  font-size: 0.75rem;
  font-weight: 600;
  background: ${props => props.$bg || PALETTE.bg};
  color: ${props => props.$color || PALETTE.text};
`;

const LoadingContainer = styled.div`
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  padding: 4rem;
  color: ${PALETTE.textLight};
  gap: 1rem;
`;

const EmptyState = styled(LoadingContainer)`
  background: ${PALETTE.card};
  border-radius: 12px;
`;

// Full-width chart container
const FullWidthChart = styled(ChartCard)`
  grid-column: 1 / -1;
`;

// ====================== UTILITAIRES ======================

const extractTimeHHMM = (timeString) => {
  if (!timeString) return null;
  const m = timeString.match(/(\d{1,2}):(\d{2})/);
  return m ? `${m[1].padStart(2,'0')}:${m[2]}` : null;
};

const extractDate = (dateStr) => {
  if (!dateStr) return null;
  // ISO
  const iso = dateStr.match(/^(\d{4})-(\d{2})-(\d{2})/);
  if (iso) return `${iso[3]}/${iso[2]}/${iso[1]}`;
  // DD/MM/YYYY
  const dmy = dateStr.match(/(\d{2})\/(\d{2})\/(\d{4})/);
  if (dmy) return `${dmy[1]}/${dmy[2]}/${dmy[3]}`;
  return null;
};

const extractHour = (timeStr) => {
  const hhmm = extractTimeHHMM(timeStr);
  if (!hhmm) return null;
  return parseInt(hhmm.split(':')[0], 10);
};

const extractAirline = (flightNumber) => {
  if (!flightNumber) return 'Inconnu';
  const match = flightNumber.match(/^([A-Z]{2})/);
  return match ? match[1] : flightNumber.substring(0, 2);
};

// ====================== COMPOSANT ======================

const StatsPage = ({ passengersFromList = [] }) => {
  const [historyData, setHistoryData] = useState([]);
  const [loading, setLoading] = useState(true);
  const [dateFrom, setDateFrom] = useState('');
  const [dateTo, setDateTo] = useState('');

  const loadData = useCallback(async () => {
    setLoading(true);
    try {
      const data = await fetchSelectedPaxHistory();
      setHistoryData(data);
    } catch (e) {
      console.error('Erreur chargement stats:', e);
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    loadData();
  }, [loadData]);

  // Combiner données live + historique (dédoublonner par uuid)
  const allData = React.useMemo(() => {
    const uuids = new Set(historyData.map(p => p.uuid));
    const fromList = passengersFromList
      .filter(p => p.selectedUuid && !uuids.has(p.selectedUuid))
      .map(p => ({
        uuid: p.selectedUuid,
        created_at: p.addedAt || '',
        idPax: p.idPax || '',
        lastName: p.lastName || '',
        firstName: p.firstName || '',
        flightNumber: p.flightNumber || '',
        departureTime: p.departureTime || '',
        goLieu: p.goLieu || '',
        goAcc: p.goAcc || '',
        ssr1: p.ssr1 || '',
        isSkyPriority: !!p.isSkyPriority,
        isAssisted: !!p.isAssisted,
      }));
    return [...historyData, ...fromList];
  }, [historyData, passengersFromList]);

  // Filtrage par date
  const filteredData = React.useMemo(() => {
    if (!dateFrom && !dateTo) return allData;
    return allData.filter(p => {
      const created = p.created_at ? new Date(p.created_at) : null;
      if (!created) return true;
      if (dateFrom && created < new Date(dateFrom)) return false;
      if (dateTo) {
        const to = new Date(dateTo);
        to.setHours(23, 59, 59);
        if (created > to) return false;
      }
      return true;
    });
  }, [allData, dateFrom, dateTo]);

  // ====================== CALCULS KPI ======================

  const stats = React.useMemo(() => {
    const data = filteredData;
    const total = data.length;
    const assisted = data.filter(p => p.isAssisted).length;
    const skyPriority = data.filter(p => p.isSkyPriority).length;
    const withAgent = data.filter(p => (p.goAcc || p.goLieu)).length;

    // Par SSR
    const ssrMap = {};
    data.forEach(p => {
      const ssr = (p.ssr1 || 'Non renseigné').toUpperCase();
      ssrMap[ssr] = (ssrMap[ssr] || 0) + 1;
    });
    const ssrData = Object.entries(ssrMap)
      .map(([name, value]) => ({ name, value }))
      .sort((a, b) => b.value - a.value);

    // Par compagnie
    const airlineMap = {};
    data.forEach(p => {
      const airline = extractAirline(p.flightNumber);
      airlineMap[airline] = (airlineMap[airline] || 0) + 1;
    });
    const airlineData = Object.entries(airlineMap)
      .map(([name, value]) => ({ name, value }))
      .sort((a, b) => b.value - a.value)
      .slice(0, 10);

    // Par heure de départ
    const hourMap = {};
    for (let h = 5; h <= 23; h++) hourMap[h] = 0;
    data.forEach(p => {
      const h = extractHour(p.departureTime);
      if (h !== null && hourMap.hasOwnProperty(h)) hourMap[h]++;
    });
    const hourData = Object.entries(hourMap)
      .map(([hour, count]) => ({ hour: `${String(hour).padStart(2,'0')}h`, count }));

    // Par jour (historique)
    const dayMap = {};
    data.forEach(p => {
      const d = extractDate(p.created_at) || extractDate(p.departureTime);
      if (d) dayMap[d] = (dayMap[d] || 0) + 1;
    });
    const dayData = Object.entries(dayMap)
      .map(([date, count]) => ({ date, count }))
      .sort((a, b) => {
        const [da, ma, ya] = a.date.split('/');
        const [db, mb, yb] = b.date.split('/');
        return new Date(ya, ma-1, da) - new Date(yb, mb-1, db);
      })
      .slice(-30); // 30 derniers jours

    // SkyPriority vs Normal
    const priorityData = [
      { name: 'SkyPriority', value: skyPriority },
      { name: 'Standard', value: total - skyPriority },
    ];

    // Assistés vs En attente
    const assistedData = [
      { name: 'Pris en charge', value: assisted },
      { name: 'En attente', value: total - assisted },
    ];

    // Avec agent vs sans
    const agentData = [
      { name: 'Agent assigné', value: withAgent },
      { name: 'Sans agent', value: total - withAgent },
    ];

    // Taux
    const assistedRate = total > 0 ? Math.round((assisted / total) * 100) : 0;
    const skyRate = total > 0 ? Math.round((skyPriority / total) * 100) : 0;
    const agentRate = total > 0 ? Math.round((withAgent / total) * 100) : 0;

    // Top vols
    const flightMap = {};
    data.forEach(p => {
      const fn = p.flightNumber || 'N/A';
      flightMap[fn] = (flightMap[fn] || 0) + 1;
    });
    const topFlights = Object.entries(flightMap)
      .map(([flight, count]) => ({ flight, count }))
      .sort((a, b) => b.count - a.count)
      .slice(0, 10);

    return {
      total, assisted, skyPriority, withAgent,
      assistedRate, skyRate, agentRate,
      ssrData, airlineData, hourData, dayData,
      priorityData, assistedData, agentData,
      topFlights,
    };
  }, [filteredData]);

  // ====================== RENDU ======================

  if (loading) {
    return (
      <PageContainer>
        <LoadingContainer>
          <FaSyncAlt size={28} className="fa-spin" />
          <span>Chargement des statistiques...</span>
        </LoadingContainer>
      </PageContainer>
    );
  }

  if (allData.length === 0) {
    return (
      <PageContainer>
        <PageHeader>
          <PageTitle><FaChartBar size={22} /> Statistiques PMR</PageTitle>
          <RefreshBtn onClick={loadData}><FaSyncAlt /> Actualiser</RefreshBtn>
        </PageHeader>
        <EmptyState>
          <FaChartBar size={48} />
          <span>Aucune donnée disponible dans l'historique</span>
        </EmptyState>
      </PageContainer>
    );
  }

  return (
    <PageContainer>
      {/* Header */}
      <PageHeader>
        <PageTitle><FaChartBar size={22} /> Statistiques PMR</PageTitle>
        <HeaderActions>
          <DateFilter>
            <FaCalendarAlt size={14} />
            <DateInput type="date" value={dateFrom} onChange={e => setDateFrom(e.target.value)} />
            <span>→</span>
            <DateInput type="date" value={dateTo} onChange={e => setDateTo(e.target.value)} />
          </DateFilter>
          <RefreshBtn onClick={loadData}><FaSyncAlt /> Actualiser</RefreshBtn>
        </HeaderActions>
      </PageHeader>

      {/* KPI Cards */}
      <KPIGrid>
        <KPICard $color={PALETTE.primary} $delay="0.05s">
          <KPIIcon $bgColor="rgba(0,86,179,0.1)" $color={PALETTE.primary}>
            <FaUserFriends size={22} />
          </KPIIcon>
          <KPIContent>
            <KPIValue>{stats.total}</KPIValue>
            <KPILabel>Total passagers PMR</KPILabel>
          </KPIContent>
        </KPICard>

        <KPICard $color={PALETTE.success} $delay="0.1s">
          <KPIIcon $bgColor="rgba(25,135,84,0.1)" $color={PALETTE.success}>
            <FaCheckCircle size={22} />
          </KPIIcon>
          <KPIContent>
            <KPIValue>{stats.assisted} <small style={{fontSize:'0.8rem',color:PALETTE.textLight}}>({stats.assistedRate}%)</small></KPIValue>
            <KPILabel>Pris en charge</KPILabel>
          </KPIContent>
        </KPICard>

        <KPICard $color={PALETTE.skyPriority} $delay="0.15s">
          <KPIIcon $bgColor="rgba(230,57,70,0.1)" $color={PALETTE.skyPriority}>
            <FaCrown size={22} />
          </KPIIcon>
          <KPIContent>
            <KPIValue>{stats.skyPriority} <small style={{fontSize:'0.8rem',color:PALETTE.textLight}}>({stats.skyRate}%)</small></KPIValue>
            <KPILabel>SkyPriority</KPILabel>
          </KPIContent>
        </KPICard>

        <KPICard $color={PALETTE.info} $delay="0.2s">
          <KPIIcon $bgColor="rgba(13,202,240,0.1)" $color={PALETTE.info}>
            <FaWalking size={22} />
          </KPIIcon>
          <KPIContent>
            <KPIValue>{stats.withAgent} <small style={{fontSize:'0.8rem',color:PALETTE.textLight}}>({stats.agentRate}%)</small></KPIValue>
            <KPILabel>Agent assigné</KPILabel>
          </KPIContent>
        </KPICard>

        <KPICard $color={PALETTE.warning} $delay="0.25s">
          <KPIIcon $bgColor="rgba(255,193,7,0.1)" $color="#856404">
            <FaWheelchair size={22} />
          </KPIIcon>
          <KPIContent>
            <KPIValue>{stats.ssrData[0]?.name || '-'}</KPIValue>
            <KPILabel>SSR le plus fréquent</KPILabel>
          </KPIContent>
        </KPICard>

        <KPICard $color="#6f42c1" $delay="0.3s">
          <KPIIcon $bgColor="rgba(111,66,193,0.1)" $color="#6f42c1">
            <FaPlane size={22} />
          </KPIIcon>
          <KPIContent>
            <KPIValue>{stats.topFlights[0]?.flight || '-'}</KPIValue>
            <KPILabel>Vol le plus concerné</KPILabel>
          </KPIContent>
        </KPICard>
      </KPIGrid>

      {/* Charts - Row 1 */}
      <ChartsGrid>
        {/* Répartition horaire */}
        <ChartCard>
          <ChartTitle><FaClock size={16} /> Répartition horaire des départs</ChartTitle>
          <ResponsiveContainer width="100%" height={280}>
            <BarChart data={stats.hourData}>
              <CartesianGrid strokeDasharray="3 3" stroke="#eee" />
              <XAxis dataKey="hour" tick={{ fontSize: 11 }} />
              <YAxis allowDecimals={false} tick={{ fontSize: 11 }} />
              <Tooltip />
              <Bar dataKey="count" name="Passagers" fill={PALETTE.primary} radius={[4,4,0,0]} />
            </BarChart>
          </ResponsiveContainer>
        </ChartCard>

        {/* Répartition par SSR */}
        <ChartCard>
          <ChartTitle><FaWheelchair size={16} /> Répartition par type SSR</ChartTitle>
          <ResponsiveContainer width="100%" height={280}>
            <PieChart>
              <Pie
                data={stats.ssrData}
                cx="50%" cy="50%"
                innerRadius={55} outerRadius={100}
                paddingAngle={3}
                dataKey="value"
                label={({ name, percent }) => `${name} (${(percent*100).toFixed(0)}%)`}
              >
                {stats.ssrData.map((_, i) => (
                  <Cell key={i} fill={PIE_COLORS[i % PIE_COLORS.length]} />
                ))}
              </Pie>
              <Tooltip />
            </PieChart>
          </ResponsiveContainer>
        </ChartCard>
      </ChartsGrid>

      {/* Charts - Row 2 */}
      <ChartsGrid>
        {/* Par compagnie */}
        <ChartCard>
          <ChartTitle><FaPlane size={16} /> Passagers par compagnie</ChartTitle>
          <ResponsiveContainer width="100%" height={280}>
            <BarChart data={stats.airlineData} layout="vertical">
              <CartesianGrid strokeDasharray="3 3" stroke="#eee" />
              <XAxis type="number" allowDecimals={false} tick={{ fontSize: 11 }} />
              <YAxis type="category" dataKey="name" width={50} tick={{ fontSize: 12, fontWeight: 600 }} />
              <Tooltip />
              <Bar dataKey="value" name="Passagers" fill={PALETTE.success} radius={[0,4,4,0]} />
            </BarChart>
          </ResponsiveContainer>
        </ChartCard>

        {/* SkyPriority / Assistés / Agent */}
        <ChartCard>
          <ChartTitle><FaPercentage size={16} /> Taux de prise en charge</ChartTitle>
          <ResponsiveContainer width="100%" height={280}>
            <PieChart>
              <Pie data={stats.assistedData} cx="30%" cy="50%" innerRadius={35} outerRadius={60} paddingAngle={3} dataKey="value">
                <Cell fill={PALETTE.success} />
                <Cell fill={PALETTE.border} />
              </Pie>
              <Pie data={stats.priorityData} cx="70%" cy="50%" innerRadius={35} outerRadius={60} paddingAngle={3} dataKey="value">
                <Cell fill={PALETTE.skyPriority} />
                <Cell fill={PALETTE.border} />
              </Pie>
              <Tooltip />
              <Legend />
            </PieChart>
          </ResponsiveContainer>
          <div style={{display:'flex',justifyContent:'space-around',marginTop:'0.5rem',fontSize:'0.8rem',color:PALETTE.textLight}}>
            <span>Prise en charge: <strong>{stats.assistedRate}%</strong></span>
            <span>SkyPriority: <strong>{stats.skyRate}%</strong></span>
          </div>
        </ChartCard>
      </ChartsGrid>

      {/* Historique par jour */}
      {stats.dayData.length > 1 && (
        <ChartsGrid>
          <FullWidthChart>
            <ChartTitle><FaCalendarAlt size={16} /> Évolution journalière</ChartTitle>
            <ResponsiveContainer width="100%" height={280}>
              <AreaChart data={stats.dayData}>
                <CartesianGrid strokeDasharray="3 3" stroke="#eee" />
                <XAxis dataKey="date" tick={{ fontSize: 10 }} />
                <YAxis allowDecimals={false} tick={{ fontSize: 11 }} />
                <Tooltip />
                <Area type="monotone" dataKey="count" name="Passagers" stroke={PALETTE.primary} fill="rgba(0,86,179,0.15)" strokeWidth={2} />
              </AreaChart>
            </ResponsiveContainer>
          </FullWidthChart>
        </ChartsGrid>
      )}

      {/* Top vols */}
      <ChartsGrid>
        <TableCard>
          <ChartTitle><FaPlane size={16} /> Top 10 vols les plus concernés</ChartTitle>
          <StatsTable>
            <thead>
              <tr>
                <th>#</th>
                <th>Vol</th>
                <th>Nb passagers PMR</th>
                <th>Part</th>
              </tr>
            </thead>
            <tbody>
              {stats.topFlights.map((f, i) => (
                <tr key={f.flight}>
                  <td><strong>{i + 1}</strong></td>
                  <td><strong>{f.flight}</strong></td>
                  <td>{f.count}</td>
                  <td>
                    <Badge
                      $bg={i === 0 ? 'rgba(0,86,179,0.1)' : PALETTE.bg}
                      $color={i === 0 ? PALETTE.primary : PALETTE.text}
                    >
                      {stats.total > 0 ? Math.round((f.count / stats.total) * 100) : 0}%
                    </Badge>
                  </td>
                </tr>
              ))}
            </tbody>
          </StatsTable>
        </TableCard>

        {/* Détail SSR */}
        <TableCard>
          <ChartTitle><FaWheelchair size={16} /> Détail par type SSR</ChartTitle>
          <StatsTable>
            <thead>
              <tr>
                <th>Type SSR</th>
                <th>Nombre</th>
                <th>Part</th>
                <th>Barre</th>
              </tr>
            </thead>
            <tbody>
              {stats.ssrData.map((s, i) => (
                <tr key={s.name}>
                  <td>
                    <Badge
                      $bg={
                        s.name === 'WCHR' ? 'rgba(25,135,84,0.15)' :
                        s.name === 'WCHS' ? 'rgba(255,193,7,0.2)' :
                        s.name === 'WCHC' ? 'rgba(220,53,69,0.15)' : PALETTE.bg
                      }
                      $color={
                        s.name === 'WCHR' ? PALETTE.success :
                        s.name === 'WCHS' ? '#856404' :
                        s.name === 'WCHC' ? PALETTE.danger : PALETTE.text
                      }
                    >
                      {s.name}
                    </Badge>
                  </td>
                  <td><strong>{s.value}</strong></td>
                  <td>{stats.total > 0 ? Math.round((s.value / stats.total) * 100) : 0}%</td>
                  <td style={{width:'40%'}}>
                    <div style={{
                      width: `${stats.total > 0 ? (s.value / stats.total) * 100 : 0}%`,
                      height: '8px',
                      borderRadius: '4px',
                      background: PIE_COLORS[i % PIE_COLORS.length],
                      minWidth: '4px',
                      transition: 'width 0.5s'
                    }} />
                  </td>
                </tr>
              ))}
            </tbody>
          </StatsTable>
        </TableCard>
      </ChartsGrid>
    </PageContainer>
  );
};

export default StatsPage;