// ✅ FONCTIONS UTILITAIRES POUR GO-ACC ET GO-LIEU
// goLieu et goAcc contiennent des horodatages quand un agent est assigné
const isAgentEnRoute = (passenger) => {
  const hasGoAcc = passenger.goAcc && passenger.goAcc.trim() !== '';
  const hasGoLieu = passenger.goLieu && passenger.goLieu.trim() !== '';
  return hasGoAcc || hasGoLieu;
};

const getAgentName = (passenger) => {
  if (passenger.goAcc && passenger.goAcc.trim() !== '') {
    return passenger.goAcc.trim();
  }
  if (passenger.goLieu && passenger.goLieu.trim() !== '') {
    return passenger.goLieu.trim();
  }
  return '';
};

const extractTimeHHMM = (timeString) => {
  if (!timeString) return "??:??";
  
  if (/^\d{1,2}:\d{2}$/.test(timeString)) {
    return timeString;
  }
  
  const dateTimeMatch = timeString.match(/(\d{1,2})[/-](\d{1,2})[/-](\d{2,4})\s+(\d{1,2}):(\d{2})/);
  if (dateTimeMatch) {
    return `${dateTimeMatch[4]}:${dateTimeMatch[5]}`;
  }
  
  const isoMatch = timeString.match(/T(\d{2}):(\d{2})/);
  if (isoMatch) {
    return `${isoMatch[1]}:${isoMatch[2]}`;
  }
  
  return timeString;
};

// ✅ MAPPING DYNAMIQUE basé sur les entêtes réels de la feuille
const HEADER_ALIASES = {
  idPax:         ['id pax d', 'id pax', 'idpax', 'id_pax'],
  lastName:      ['nom', 'lastname', 'last_name', 'name'],
  firstName:     ['prénom', 'prenom', 'firstname', 'first_name'],
  flightNumber:  ['num vol d', 'num vol', 'vol', 'flight', 'flightnumber', 'flight_number'],
  departureTime: ['etd', 'std', 'heure', 'departure', 'departuretime', 'departure_time'],
  goLieu:        ['go-lieu', 'golieu', 'go_lieu', 'go lieu'],
  goAcc:         ['go-acc', 'goacc', 'go_acc', 'go acc'],
  ssr1:          ['ssr1', 'ssr', 'handicap', 'status'],
  terminalDepart:['terminal d', 'terminal', 'term'],
};

const buildColumnMap = (headerRow) => {
  const map = {};
  const normalizedHeaders = headerRow.map(h => String(h || '').trim().toLowerCase());
  
  console.log("📋 Entêtes de la feuille Jalons:", headerRow);
  console.log("📋 Entêtes normalisés:", normalizedHeaders);
  
  for (const [field, aliases] of Object.entries(HEADER_ALIASES)) {
    const idx = normalizedHeaders.findIndex(h => aliases.includes(h));
    if (idx !== -1) {
      map[field] = idx;
    }
  }
  
  console.log("📋 Mapping colonnes:", map);
  return map;
};

const parseSheetData = (values) => {
  if (!values || !Array.isArray(values) || values.length === 0) {
    return {};
  }

  console.log("🔄 RAFRAÎCHISSEMENT - Analyse des données Sheet:");
  console.log("Nombre de lignes:", values.length);

  // ✅ Construire le mapping à partir des entêtes
  const headerRow = values[0];
  // Gérer le cas où les entêtes sont dans une seule cellule avec point-virgule
  let processedHeader = headerRow;
  if (headerRow.length === 1 && String(headerRow[0]).includes(';')) {
    processedHeader = String(headerRow[0]).split(';').map(cell => cell.trim());
  }
  const colMap = buildColumnMap(processedHeader);

  const sheetDataMap = {};
  
  for (let i = 1; i < values.length; i++) {
    const row = values[i];
    
    let processedRow = row;
    if (row.length === 1 && String(row[0]).includes(';')) {
      processedRow = String(row[0]).split(';').map(cell => cell.trim());
    }
    
    const get = (field) => String(processedRow[colMap[field]] ?? '').trim();
    
    const idPax = get('idPax');
    const lastName = get('lastName');
    
    if (idPax && lastName) {
      sheetDataMap[idPax] = {
        idPax,
        lastName,
        firstName:      get('firstName'),
        flightNumber:   get('flightNumber'),
        departureTime:  get('departureTime'),
        goLieu:         get('goLieu'),
        goAcc:          get('goAcc'),
        ssr1:           get('ssr1'),
      };
      
      // Log de debug pour les premiers passagers
      if (i <= 3) {
        console.log(`🔄 Ligne ${i} - ${lastName}:`, sheetDataMap[idPax]);
      }
    }
  }
  
  console.log(`🔄 Sheet mappé: ${Object.keys(sheetDataMap).length} passagers`);
  return sheetDataMap;
};

const extractDateTimeInfo = (timeString) => {
  if (!timeString) return { date: "", time: "??:??", fullDateTime: null };
  
  console.log(`🔍 Analyse du departureTime: "${timeString}"`);
  
  const dateTimeMatch = timeString.match(/(\d{1,2})[/-](\d{1,2})[/-](\d{2,4})\s+(\d{1,2}):(\d{2})/);
  if (dateTimeMatch) {
    const day = dateTimeMatch[1].padStart(2, '0');
    const month = dateTimeMatch[2].padStart(2, '0');
    const year = dateTimeMatch[3].length === 2 ? `20${dateTimeMatch[3]}` : dateTimeMatch[3];
    const hours = dateTimeMatch[4].padStart(2, '0');
    const minutes = dateTimeMatch[5];
    
    const fullDateTime = new Date(year, month - 1, day, hours, minutes);
    
    return {
      date: `${day}/${month}`,
      time: `${hours}:${minutes}`,
      fullDateTime
    };
  }
  
  if (/^\d{1,2}:\d{2}$/.test(timeString)) {
    const today = new Date();
    const [hours, minutes] = timeString.split(':').map(Number);
    const fullDateTime = new Date(today.getFullYear(), today.getMonth(), today.getDate(), hours, minutes);
    
    return {
      date: "",
      time: timeString,
      fullDateTime
    };
  }
  
  return { date: "", time: timeString, fullDateTime: null };
};

const PassengerList = ({ passengers: initialPassengers, setPassengers }) => {
  const [isRefreshing, setIsRefreshing] = useState(false);
  const refreshIntervalRef = useRef(null);
  const agentStatusRef = useRef({});
  
  const passengers = initialPassengers || [];
  const updatePassengers = setPassengers || (() => {});

  // ✅ FIX: Ref qui pointe toujours vers la dernière version des passagers
  // Cela évite le problème de stale closure dans refreshData et les setTimeout
  const passengersRef = useRef(passengers);
  useEffect(() => {
    passengersRef.current = passengers;
  }, [passengers]);
  
  // Calculer les compteurs (seulement les vols non passés)
  const now = new Date();
  const activePassengers = passengers.filter(p => {
    const timeHHMM = extractTimeHHMM(p.departureTime);
    if (!timeHHMM || timeHHMM === "??:??") return true;
    
    try {
      const [hours, minutes] = timeHHMM.split(':').map(Number);
      if (isNaN(hours) || isNaN(minutes)) return true;
      
      const departureDate = new Date();
      departureDate.setHours(hours, minutes, 0, 0);
      
      return departureDate >= now;
    } catch (e) {
      return true;
    }
  });
  
  const activeCount = activePassengers.length;
  const skyPriorityCount = activePassengers.filter(p => p.isSkyPriority).length;

  // ✅ FIX: refreshData utilise passengersRef.current au lieu de passengers
  const refreshData = async () => {
    const currentPassengers = passengersRef.current; // ✅ Toujours la version à jour
    
    if (currentPassengers.length === 0) {
      console.log("⏭️ Pas de passagers, pas de rafraîchissement");
      return;
    }
    
    try {
      setIsRefreshing(true);
      console.log("🔄 Rafraîchissement en cours...");
      
      const SHEET_ID = process.env.REACT_APP_SHEET_ID;
      const SHEET_RANGE = process.env.REACT_APP_SHEET_RANGE;
      const API_KEY = process.env.REACT_APP_GOOGLE_API_KEY;
      
      if (!API_KEY) {
        console.warn("⚠️ Pas de clé API - rafraîchissement impossible");
        return;
      }
      
      const url = `https://sheets.googleapis.com/v4/spreadsheets/${SHEET_ID}/values/${SHEET_RANGE}?key=${API_KEY}`;
      const response = await fetch(url);
      
      if (!response.ok) {
        throw new Error(`Erreur HTTP: ${response.status}`);
      }
      
      const data = await response.json();
      const sheetDataMap = parseSheetData(data.values);
      
      let hasChanges = false;
      const allChanges = [];
      const agentEnRouteActivations = []; // ✅ IDs des passagers avec nouvelle animation agent
      const updatedPassengers = currentPassengers.map(passenger => { // ✅ currentPassengers
        const sheetEntry = sheetDataMap[passenger.idPax];
        
        if (sheetEntry) {
          const currentGoAcc = String(passenger.goAcc || '').trim();
          const newGoAcc = String(sheetEntry.goAcc || '').trim();
          const currentGoLieu = String(passenger.goLieu || '').trim();
          const newGoLieu = String(sheetEntry.goLieu || '').trim();
          const currentDepartureTime = String(passenger.departureTime || '').trim();
          const newDepartureTime = String(sheetEntry.departureTime || '').trim();
          const currentFlightNumber = String(passenger.flightNumber || '').trim();
          const newFlightNumber = String(sheetEntry.flightNumber || '').trim();
          
          const goAccChanged = currentGoAcc !== newGoAcc;
          const goLieuChanged = currentGoLieu !== newGoLieu;
          const departureTimeChanged = currentDepartureTime !== newDepartureTime;
          const flightNumberChanged = currentFlightNumber !== newFlightNumber;
          
          if (goAccChanged || goLieuChanged || departureTimeChanged || flightNumberChanged) {
            hasChanges = true;
            
            const changes = [];
            if (goAccChanged) changes.push(`GO-ACC: "${currentGoAcc}" → "${newGoAcc}"`);
            if (goLieuChanged) changes.push(`GO-LIEU: "${currentGoLieu}" → "${newGoLieu}"`);
            if (departureTimeChanged) changes.push(`HEURE: "${currentDepartureTime}" → "${newDepartureTime}"`);
            if (flightNumberChanged) changes.push(`VOL: "${currentFlightNumber}" → "${newFlightNumber}"`);
            
            allChanges.push(...changes);
            
            console.log(`🔄 Changements détectés pour ${passenger.lastName}:`, changes.join(', '));
            
            if (goAccChanged || goLieuChanged) {
              const wasAgentEnRoute = isAgentEnRoute(passenger);
              const updatedPassengerTemp = { ...passenger, goAcc: newGoAcc, goLieu: newGoLieu };
              const isNowAgentEnRoute = isAgentEnRoute(updatedPassengerTemp);
              
              if (!wasAgentEnRoute && isNowAgentEnRoute) {
                // ✅ Marquer le passager pour l'animation (visible par TVDisplay via localStorage)
                hasChanges = true;
                agentEnRouteActivations.push({
                  passengerId: passenger.id,
                  agentName: getAgentName(updatedPassengerTemp),
                  changeSource: goAccChanged ? 'GO-ACC' : 'GO-LIEU'
                });
                
                setTimeout(() => {
                  const event = new CustomEvent('agentStatusChanged', {
                    detail: {
                      passengerId: passenger.id,
                      idPax: passenger.idPax,
                      hasAgent: isNowAgentEnRoute,
                      isNew: true,
                      isRemoved: false,
                      agentName: getAgentName(updatedPassengerTemp),
                      changeSource: goAccChanged ? 'GO-ACC' : 'GO-LIEU'
                    }
                  });
                  window.dispatchEvent(event);
                  console.log(`🎬 Événement dispatché pour ${passenger.lastName} (${getAgentName(updatedPassengerTemp)})`);
                }, 100);
              }
            }
          }

          if (passenger.selectedUuid) {
            try {
              // ✅ FIX: N'envoyer que les champs qui ont réellement changé
              const changedFields = {};
              if (goAccChanged) changedFields.goAcc = newGoAcc || '';
              if (goLieuChanged) changedFields.goLieu = newGoLieu || '';
              if (departureTimeChanged) changedFields.departureTime = newDepartureTime || '';
              if (flightNumberChanged) changedFields.flightNumber = newFlightNumber || '';
              
              if (Object.keys(changedFields).length > 0) {
                updateSelectedPassenger(passenger.selectedUuid, changedFields);
                console.log(`📝 Sheet selected_pax mise à jour pour ${passenger.lastName}:`, changedFields);
              }
            } catch (_) {}
          }
          
          // ✅ FIX: On ne touche qu'aux champs provenant de la Sheet
          // isSkyPriority et les autres champs locaux sont préservés via le spread
          const isNewlyActivated = agentEnRouteActivations.some(a => a.passengerId === passenger.id);
          return {
            ...passenger, // ← préserve isSkyPriority, id, addedAt, selectedUuid, etc.
            goAcc: newGoAcc,
            goLieu: newGoLieu,
            departureTime: newDepartureTime,
            flightNumber: newFlightNumber,
            lastName: sheetEntry.lastName || passenger.lastName,
            firstName: sheetEntry.firstName || passenger.firstName,
            // ✅ Flag pour TVDisplay : true uniquement lors de la transition
            isAgentEnRouteActive: isNewlyActivated ? true : (passenger.isAgentEnRouteActive || false)
          };
        }
        
        return passenger;
      });
      
      if (hasChanges) {
        console.log("✅ Mise à jour des passagers avec changements");
        updatePassengers(updatedPassengers);
        
        // ✅ Auto-désactiver l'animation "Agent en route" après 30 secondes
        if (agentEnRouteActivations.length > 0) {
          const activatedIds = agentEnRouteActivations.map(a => a.passengerId);
          console.log(`🎬 Animation agent en route activée pour: ${activatedIds.length} passager(s)`);
          
          setTimeout(() => {
            const latest = passengersRef.current;
            const cleared = latest.map(p => 
              activatedIds.includes(p.id) ? { ...p, isAgentEnRouteActive: false } : p
            );
            updatePassengers(cleared);
            console.log(`🎬 Animation agent en route désactivée pour: ${activatedIds.length} passager(s)`);
          }, 30000); // 30 secondes d'animation
        }
        
        const hasNewPassengers = allChanges.some(change => 
          change.includes('HEURE:') || change.includes('VOL:') || allChanges.length > 2
        );
        
        if (hasNewPassengers) {
          setTimeout(() => {
            console.log("🔄 Rafraîchissement automatique du PassengerSelector (changements détectés)");
            window.dispatchEvent(new CustomEvent('refreshPassengerSelector'));
          }, 2000);
        }
      } else {
        console.log("ℹ️ Aucun changement détecté");
      }
      
    } catch (error) {
      console.error("❌ Erreur rafraîchissement:", error);
    } finally {
      setIsRefreshing(false);
    }
  };

  const handlePassengerSelect = async (passenger) => {
    if (passenger) {
      const now = new Date();
      const newPassenger = {
        ...passenger,
        id: `passenger-${Date.now()}-${Math.random().toString(36).substr(2, 9)}`,
        addedAt: now.toLocaleTimeString('fr-FR', { hour:'2-digit', minute:'2-digit' }),
        isSkyPriority: false,
        isAgentEnRouteActive: false,
        goLieu: passenger.goLieu || ''
      };

      try {
        const { uuid } = await appendSelectedPassenger(newPassenger);
        const withPersist = { ...newPassenger, selectedUuid: uuid };
        updatePassengers([...passengersRef.current, withPersist]); // ✅ passengersRef
        
        setTimeout(() => {
          console.log("🔄 Rafraîchissement automatique du PassengerSelector après ajout");
          window.dispatchEvent(new CustomEvent('refreshPassengerSelector'));
        }, 1000);
        
      } catch (err) {
        console.error('❌ Echec append selected_pax:', err);
        return;
      }
    }
  };

  const handleToggleSkyPriority = (passengerId) => {
    const currentPassengers = passengersRef.current;
    const pax = currentPassengers.find(p => p.id === passengerId);
    if (!pax) return;

    const newVal = !pax.isSkyPriority;
    const updated = currentPassengers.map(p =>
      p.id === passengerId ? { ...p, isSkyPriority: newVal } : p
    );
    updatePassengers(updated);

    // ✅ FIX: Log + vérification selectedUuid
    if (pax.selectedUuid) {
      try {
        updateSelectedPassenger(pax.selectedUuid, { isSkyPriority: newVal });
        console.log(`📝 isSkyPriority=${newVal} envoyé à la sheet pour ${pax.lastName} (uuid: ${pax.selectedUuid})`);
      } catch (_) {}
    } else {
      console.warn(`⚠️ Pas de selectedUuid pour ${pax.lastName} (id: ${passengerId}), sheet non mise à jour`);
    }
  };

  const handleRemovePassenger = (passengerId) => {
    console.log("🗑️ Suppression du passager:", passengerId);
    const currentPassengers = passengersRef.current; // ✅ passengersRef
    const pax = currentPassengers.find(p => p.id === passengerId);

    const updated = currentPassengers.filter(p => p.id !== passengerId);
    updatePassengers(updated);

    if (pax?.selectedUuid) deleteRowByUuid(pax.selectedUuid);
  };

  // ✅ FIX: L'effet ne dépend plus de passengers.length mais utilise un setup unique
  useEffect(() => {
    console.log("🔄 Démarrage du rafraîchissement automatique");
    
    // Premier rafraîchissement
    const timeout = setTimeout(refreshData, 2000);
    
    // Rafraîchissement périodique
    refreshIntervalRef.current = setInterval(refreshData, 10000);
    
    return () => {
      clearTimeout(timeout);
      if (refreshIntervalRef.current) {
        clearInterval(refreshIntervalRef.current);
      }
    };
  }, []); // ✅ [] — un seul setup, refreshData lit passengersRef.current

  const handleMarkAsAssisted = (passengerId) => {
    console.log("✅ Marquage PMR assisté:", passengerId);
    const now = new Date();
    const currentPassengers = passengersRef.current;
    const pax = currentPassengers.find(p => p.id === passengerId);
    
    const updated = currentPassengers.map(p =>
      p.id === passengerId ? { 
        ...p, 
        isAssisted: true,
        assistedAt: now.toLocaleTimeString('fr-FR', { hour: '2-digit', minute: '2-digit' })
      } : p
    );
    updatePassengers(updated);
    
    // ✅ Pousser isAssisted=TRUE vers la sheet selected_pax (sans supprimer la ligne)
    if (pax?.selectedUuid) {
      try {
        updateSelectedPassenger(pax.selectedUuid, { isAssisted: true });
        console.log(`📝 isAssisted=true envoyé à la sheet pour ${pax.lastName} (uuid: ${pax.selectedUuid})`);
      } catch (_) {}
    } else {
      console.warn(`⚠️ Pas de selectedUuid pour ${passengerId}, sheet non mise à jour`);
    }
    
    // Retirer de l'affichage après 5 secondes (la ligne reste dans selected_pax pour l'historique)
    setTimeout(() => {
      const latest = passengersRef.current;
      const filtered = latest.filter(p => p.id !== passengerId);
      updatePassengers(filtered);
      console.log(`🗑️ Passager assisté retiré de l'affichage: ${passengerId} (conservé dans selected_pax)`);
    }, 5000);
  };

  const refreshPassengerList = () => {
    console.log("🔄 Rafraîchissement manuel de la liste des passagers...");
    window.dispatchEvent(new CustomEvent('refreshPassengerSelector'));
  };

  // ✅ RESTAURATION depuis selected_pax
  const [isRestoring, setIsRestoring] = useState(false);
  
  const handleRestore = async () => {
    if (!window.confirm('Restaurer les passagers du jour depuis l\'historique ?\nCela remplacera la liste actuelle par les passagers non assistés d\'aujourd\'hui.')) {
      return;
    }
    
    setIsRestoring(true);
    try {
      console.log("🔄 Restauration depuis selected_pax (journée en cours)...");
      const history = await fetchSelectedPaxHistory();
      
      // ✅ Filtrer uniquement la journée en cours
      const today = new Date();
      const todayStr = today.toISOString().slice(0, 10); // "YYYY-MM-DD"
      const todayDMY = `${String(today.getDate()).padStart(2,'0')}/${String(today.getMonth()+1).padStart(2,'0')}/${today.getFullYear()}`; // "DD/MM/YYYY"
      
      const todayOnly = history.filter(p => {
        const ca = p.created_at || '';
        const dt = p.departureTime || '';
        // Vérifier created_at (ISO) ou departureTime (DD/MM/YYYY)
        return ca.startsWith(todayStr) || dt.startsWith(todayDMY);
      });
      
      console.log(`📊 ${history.length} total → ${todayOnly.length} aujourd'hui (${todayStr})`);
      const restored = convertToPassengerListFormat(todayOnly);
      
      if (restored.length === 0) {
        alert('Aucun passager non assisté à restaurer pour aujourd\'hui.');
        return;
      }
      
      updatePassengers(restored);
      console.log(`✅ ${restored.length} passagers restaurés depuis selected_pax`);
      alert(`✅ ${restored.length} passagers du jour restaurés avec succès.`);
    } catch (error) {
      console.error("❌ Erreur restauration:", error);
      alert('❌ Erreur lors de la restauration.');
    } finally {
      setIsRestoring(false);
    }
  };

  const sortedPassengers = [...passengers].sort((a, b) => {
    const timeA = extractTimeHHMM(a.departureTime);
    const timeB = extractTimeHHMM(b.departureTime);

    if (!timeA && !timeB) return 0;
    if (!timeA) return 1;
    if (!timeB) return -1;

    const [hoursA, minutesA] = timeA.split(':').map(Number);
    const [hoursB, minutesB] = timeB.split(':').map(Number);

    const dateA = new Date();
    dateA.setHours(hoursA, minutesA, 0, 0);

    const dateB = new Date();
    dateB.setHours(hoursB, minutesB, 0, 0);

    return dateA - dateB;
  });

  return (
    <ListContainer>
      <ListHeader>
        <TitleSection>
          <TitleIcon>
            <FaUserFriends size={20} />
          </TitleIcon>
          <Title>Passagers PMR en attente d'assistance</Title>
        </TitleSection>
        
        <SelectorSection>
          <PassengerSelector onSelect={handlePassengerSelect} />
          
          <PassengerCounter>
            <FaUserFriends size={20} />
            <CountNumber>{activeCount}</CountNumber>
            <span>passagers</span>
          </PassengerCounter>
          
          <SkyPriorityCounter>
            <FaCrown size={20} color="#FFD700" />
            <CountNumber>{skyPriorityCount}</CountNumber>
            <span>SkyPriority</span>
          </SkyPriorityCounter>
          
          {/*
          <RefreshButton onClick={refreshData} disabled={isRefreshing}>
            <FaSyncAlt className={isRefreshing ? 'fa-spin' : ''} />
            {isRefreshing ? 'Synchronisation...' : 'Actualiser'}
          </RefreshButton>*/}
          
          <RefreshButtonGreen onClick={refreshPassengerList} disabled={isRefreshing}>
            <FaSyncAlt />
            Actualiser liste
          </RefreshButtonGreen>
          
          <RestoreButton onClick={handleRestore} disabled={isRestoring}>
            <FaCloudDownloadAlt />
            {isRestoring ? 'Restauration...' : 'Restaurer'}
          </RestoreButton>
        </SelectorSection>
      </ListHeader>
      
      {passengers.length > 0 ? (
        <ListContent>
          {sortedPassengers.map((passenger) => (
          <PassengerItem 
            key={passenger.id}
            passenger={passenger} 
            onToggleSkyPriority={handleToggleSkyPriority}
            onMarkAsAssisted={handleMarkAsAssisted}
            onRemove={handleRemovePassenger}
            extractDateTimeInfo={extractDateTimeInfo}
          />
          ))}
        </ListContent>
      ) : (
        <EmptyList>
          <EmptyText>Aucun passager PMR enregistré</EmptyText>
        </EmptyList>
      )}
    </ListContainer>
  );
};

export default PassengerList;