import React, { useState, useEffect } from 'react';
import PropTypes from 'prop-types';
import styled from 'styled-components';

// Styled Components
const SelectorContainer = styled.div`
  margin-bottom: 1.2rem;
  position: relative;
  width: 100%;
  max-width: 500px;
`;

const SelectStyled = styled.select`
  appearance: none;
  background-color: #f8f9fa;
  background-image: url("data:image/svg+xml;charset=UTF-8,%3csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24' fill='none' stroke='%23495057' stroke-width='2' stroke-linecap='round' stroke-linejoin='round'%3e%3cpolyline points='6 9 12 15 18 9'%3e%3c/polyline%3e%3c/svg%3e");
  background-repeat: no-repeat;
  background-position: right 1rem center;
  background-size: 1em;
  border: 2px solid #e9ecef;
  border-radius: 0.5rem;
  box-shadow: 0 2px 5px rgba(0, 0, 0, 0.08);
  color: #495057;
  display: block;
  font-size: 1rem;
  font-weight: 500;
  line-height: 1.5;
  padding: 0.8rem 2.5rem 0.8rem 1rem;
  transition: all 0.2s ease-in-out;
  width: 100%;
  
  &:focus {
    border-color: #0056b3;
    box-shadow: 0 0 0 3px rgba(0, 86, 179, 0.25);
    outline: none;
  }
  
  &:hover {
    border-color: #ced4da;
  }
`;

const LoadingIndicator = styled.div`
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 1rem;
  background-color: #f8f9fa;
  border-radius: 0.5rem;
  color: #495057;
  font-weight: 500;
  box-shadow: 0 2px 5px rgba(0, 0, 0, 0.08);
  
  &::before {
    content: "";
    width: 1.2rem;
    height: 1.2rem;
    margin-right: 0.75rem;
    border: 3px solid #e9ecef;
    border-top-color: #0056b3;
    border-radius: 50%;
    animation: spinner 0.8s linear infinite;
  }
  
  @keyframes spinner {
    to {
      transform: rotate(360deg);
    }
  }
`;

const ErrorMessage = styled.div`
  background-color: rgba(220, 53, 69, 0.1);
  border-left: 4px solid #dc3545;
  color: #dc3545;
  font-size: 0.9rem;
  margin-top: 0.75rem;
  padding: 0.75rem;
  border-radius: 0.25rem;
`;

// Fonction utilitaire pour extraire l'heure au format HH:MM
const extractTimeHHMM = (timeString) => {
  if (!timeString) return null;
  
  if (/^\d{1,2}:\d{2}$/.test(timeString)) {
    return timeString;
  }
  
  const dateTimeMatch = timeString.match(/(\d{1,2})[/-](\d{1,2})[/-](\d{2,4})\s+(\d{1,2}):(\d{2})/);
  if (dateTimeMatch) {
    return `${dateTimeMatch[4]}:${dateTimeMatch[5]}`;
  }
  
  const isoMatch = timeString.match(/T(\d{2}):(\d{2})/);
  if (isoMatch) {
    return `${isoMatch[1]}:${isoMatch[2]}`;
  }
  
  return null;
};

// Fonction pour vérifier si un vol est passé
const isFlightPassed = (departureTime) => {
  const timeHHMM = extractTimeHHMM(departureTime);
  if (!timeHHMM) return false;
  
  try {
    const [hours, minutes] = timeHHMM.split(':').map(Number);
    if (isNaN(hours) || isNaN(minutes)) return false;
    
    const now = new Date();
    const departureDate = new Date();
    departureDate.setHours(hours, minutes, 0, 0);
    
    return departureDate < now;
  } catch (e) {
    return false;
  }
};

// ✅ MAPPING DYNAMIQUE basé sur les entêtes réels de la feuille
const HEADER_ALIASES = {
  idPax:         ['id pax d', 'id pax', 'idpax', 'id_pax'],
  lastName:      ['nom', 'lastname', 'last_name', 'name'],
  firstName:     ['prénom', 'prenom', 'firstname', 'first_name'],
  flightNumber:  ['num vol d', 'num vol', 'vol', 'flight', 'flightnumber', 'flight_number'],
  departureTime: ['etd', 'std', 'heure', 'departure', 'departuretime', 'departure_time'],
  goLieu:        ['go-lieu', 'golieu', 'go_lieu', 'go lieu'],
  goAcc:         ['go-acc', 'goacc', 'go_acc', 'go acc'],
  ssr1:          ['ssr1', 'ssr', 'handicap', 'status'],
  terminalDepart:['terminal d', 'terminal', 'term'],
};

const buildColumnMap = (headerRow) => {
  const map = {};
  const normalizedHeaders = headerRow.map(h => String(h || '').trim().toLowerCase());
  
  console.log("📋 [Selector] Entêtes de la feuille Jalons:", headerRow);
  console.log("📋 [Selector] Entêtes normalisés:", normalizedHeaders);
  
  for (const [field, aliases] of Object.entries(HEADER_ALIASES)) {
    const idx = normalizedHeaders.findIndex(h => aliases.includes(h));
    if (idx !== -1) {
      map[field] = idx;
    }
  }
  
  console.log("📋 [Selector] Mapping colonnes:", map);
  return map;
};

const parseSheetData = (values) => {
  if (!values || !Array.isArray(values) || values.length === 0) {
    return [];
  }

  console.log("📊 ANALYSE DES DONNÉES Google Sheet:");
  console.log("Nombre total de lignes:", values.length);

  // ✅ Construire le mapping à partir des entêtes
  const headerRow = values[0];
  let processedHeader = headerRow;
  if (headerRow.length === 1 && String(headerRow[0]).includes(';')) {
    processedHeader = String(headerRow[0]).split(';').map(cell => cell.trim());
  }
  const colMap = buildColumnMap(processedHeader);

  const passengers = [];
  
  for (let i = 1; i < values.length; i++) {
    const row = values[i];
    
    let processedRow = row;
    if (row.length === 1 && String(row[0]).includes(';')) {
      processedRow = String(row[0]).split(';').map(cell => cell.trim());
    }
    
    const get = (field) => String(processedRow[colMap[field]] ?? '').trim();
    
    const idPax = get('idPax');
    const lastName = get('lastName');
    
    if (idPax && lastName) {
      const passenger = {
        id: `passenger-${Date.now()}-${Math.random().toString(36).substr(2, 9)}`,
        idPax,
        lastName,
        firstName:      get('firstName'),
        flightNumber:   get('flightNumber'),
        departureTime:  get('departureTime'),
        goLieu:         get('goLieu'),
        goAcc:          get('goAcc'),
        ssr1:           get('ssr1'),
        terminalDepart: get('terminalDepart'),
        status:         get('ssr1') || 'WCHR',
        airline: '',
        destination: ''
      };
      
      // Log de debug pour les premiers passagers
      if (i <= 3) {
        console.log(`📊 Ligne ${i} - ${lastName}:`, {
          idPax: passenger.idPax,
          departureTime: passenger.departureTime,
          goLieu: `"${passenger.goLieu}"`,
          goAcc: `"${passenger.goAcc}"`,
          ssr1: `"${passenger.ssr1}"`
        });
      }
      
      passengers.push(passenger);
    }
  }
  
  console.log(`✅ Total passagers traités: ${passengers.length}`);
  return passengers;
};

// Fonction de tri alphabétique
const sortByLastName = (a, b) => {
  const lastNameA = (a.lastName || '').toLowerCase();
  const lastNameB = (b.lastName || '').toLowerCase();
  
  const nameComparison = lastNameA.localeCompare(lastNameB);
  
  if (nameComparison === 0) {
    const firstNameA = (a.firstName || '').toLowerCase();
    const firstNameB = (b.firstName || '').toLowerCase();
    return firstNameA.localeCompare(firstNameB);
  }
  
  return nameComparison;
};

const PassengerSelector = ({ onSelect }) => {
  const [passengers, setPassengers] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [selectedPassengerId, setSelectedPassengerId] = useState('');

  const fetchPassengers = async () => {
    try {
      setLoading(true);
      setError(null);
      
      const SHEET_ID = process.env.REACT_APP_SHEET_ID || '1p5Pbkam5yhXMcA7HoaksPlslf9Y9Z8X9ZLFLpUz-r_w';
      const SHEET_RANGE = process.env.REACT_APP_SHEET_RANGE || 'Jalons!A1:I5000';
      const API_KEY = process.env.REACT_APP_GOOGLE_API_KEY;
      
      console.log("🔧 PassengerSelector Configuration:", {
        SHEET_ID,
        SHEET_RANGE,
        API_KEY_DEFINED: !!API_KEY
      });
      
      if (!API_KEY) {
        throw new Error("Clé API Google non définie");
      }
      
      const url = `https://sheets.googleapis.com/v4/spreadsheets/${SHEET_ID}/values/${SHEET_RANGE}?key=${API_KEY}`;
      const response = await fetch(url);
      
      if (!response.ok) {
        throw new Error(`Erreur HTTP: ${response.status}`);
      }
      
      const data = await response.json();
      const passengersData = parseSheetData(data.values);
      
      // Filtrer les vols passés
      const currentPassengers = passengersData.filter(passenger => {
        const isPassed = isFlightPassed(passenger.departureTime);
        if (isPassed) {
          console.log(`🚫 Vol passé exclu: ${passenger.lastName} ${passenger.firstName} (${passenger.departureTime})`);
        }
        return !isPassed;
      });
      
      const sortedPassengers = [...currentPassengers].sort(sortByLastName);
      
      setPassengers(sortedPassengers);
      console.log(`✅ PassengerSelector: ${sortedPassengers.length} passagers actifs chargés (${passengersData.length - sortedPassengers.length} vols passés exclus)`);
      
    } catch (err) {
      console.error("❌ Erreur PassengerSelector:", err);
      setError(err.message);
      setPassengers([]);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchPassengers();
  }, []);

  useEffect(() => {
    const handleRefreshEvent = () => {
      console.log("🔄 Rafraîchissement du PassengerSelector demandé");
      setSelectedPassengerId('');
      fetchPassengers();
    };
    
    window.addEventListener('refreshPassengerSelector', handleRefreshEvent);
    
    return () => {
      window.removeEventListener('refreshPassengerSelector', handleRefreshEvent);
    };
  }, []);

  const handleChange = (e) => {
    const passengerId = e.target.value;
    setSelectedPassengerId(passengerId);
    
    if (passengerId) {
      const selected = passengers.find(p => p.id === passengerId);
      if (selected && onSelect) {
        console.log("✅ Passager sélectionné:", {
          nom: `${selected.lastName} ${selected.firstName}`,
          idPax: selected.idPax,
          departureTime: selected.departureTime,
          goAcc: `"${selected.goAcc}"`,
          goLieu: `"${selected.goLieu}"`,
          ssr1: `"${selected.ssr1}"`
        });
        onSelect(selected);
        setSelectedPassengerId('');
      }
    } else if (onSelect) {
      onSelect(null);
    }
  };

  if (loading) {
    return <LoadingIndicator>Chargement des passagers...</LoadingIndicator>;
  }

  if (error) {
    return <ErrorMessage>Erreur: {error}</ErrorMessage>;
  }

  return (
    <SelectorContainer>
      <SelectStyled
        value={selectedPassengerId}
        onChange={handleChange}
        aria-label="Sélectionner un passager"
      >
        <option value="">
          Sélectionner un passager ({passengers.length})
        </option>
        {passengers.map((passenger) => (
          <option key={passenger.id} value={passenger.id}>
            {passenger.lastName} {passenger.firstName} - {passenger.flightNumber} - {passenger.departureTime}
          </option>
        ))}
      </SelectStyled>
    </SelectorContainer>
  );
};

PassengerSelector.propTypes = {
  onSelect: PropTypes.func.isRequired
};

export default PassengerSelector;