// src/services/SelectedPaxReader.js
// Service de lecture de la feuille selected_pax (historique + restauration)

import { getCurrentSheetId } from '../config/siteConfig';

const API_KEY = process.env.REACT_APP_GOOGLE_API_KEY;

/**
 * Récupère toutes les lignes de selected_pax depuis Google Sheets
 * @returns {Array} Liste des passagers avec toutes leurs données
 */
export async function fetchSelectedPaxHistory() {
  const sheetId = getCurrentSheetId();
  if (!sheetId || !API_KEY) {
    console.error('❌ fetchSelectedPaxHistory: sheetId ou API_KEY manquant');
    return [];
  }

  const range = 'selected_pax!A1:M5000';
  const url = `https://sheets.googleapis.com/v4/spreadsheets/${sheetId}/values/${range}?key=${API_KEY}`;

  try {
    console.log('📊 Lecture de selected_pax...');
    const response = await fetch(url);
    
    if (!response.ok) {
      throw new Error(`Erreur HTTP ${response.status}`);
    }
    
    const data = await response.json();
    const values = data.values;
    
    if (!values || values.length < 2) {
      console.log('📊 selected_pax: aucune donnée');
      return [];
    }

    // Mapping dynamique par entêtes
    const headers = values[0].map(h => String(h || '').trim().toLowerCase());
    console.log('📊 Entêtes selected_pax:', values[0]);

    const colOf = (name) => headers.indexOf(name.toLowerCase());

    const COL = {
      uuid:           colOf('uuid'),
      created_at:     colOf('created_at'),
      site_id:        colOf('site_id'),
      idPax:          colOf('idpax'),
      lastName:       colOf('lastname'),
      firstName:      colOf('firstname'),
      flightNumber:   colOf('flightnumber'),
      departureTime:  colOf('departuretime'),
      goLieu:         colOf('golieu'),
      goAcc:          colOf('goacc'),
      ssr1:           colOf('ssr1'),
      isSkyPriority:  colOf('isskypriority'),
      isAssisted:     colOf('isassisted'),
    };

    console.log('📊 Mapping colonnes selected_pax:', COL);

    const passengers = [];
    for (let i = 1; i < values.length; i++) {
      const row = values[i];
      const get = (col) => (col >= 0 ? String(row[col] ?? '').trim() : '');

      const passenger = {
        uuid:           get(COL.uuid),
        created_at:     get(COL.created_at),
        site_id:        get(COL.site_id),
        idPax:          get(COL.idPax),
        lastName:       get(COL.lastName),
        firstName:      get(COL.firstName),
        flightNumber:   get(COL.flightNumber),
        departureTime:  get(COL.departureTime),
        goLieu:         get(COL.goLieu),
        goAcc:          get(COL.goAcc),
        ssr1:           get(COL.ssr1),
        isSkyPriority:  get(COL.isSkyPriority) === 'TRUE',
        isAssisted:     get(COL.isAssisted) === 'TRUE',
      };

      if (passenger.uuid && passenger.lastName) {
        passengers.push(passenger);
      }
    }

    console.log(`📊 selected_pax: ${passengers.length} passagers chargés`);
    return passengers;

  } catch (error) {
    console.error('❌ Erreur lecture selected_pax:', error);
    return [];
  }
}

/**
 * Convertit les données selected_pax en format compatible avec PassengerList
 * (pour la restauration)
 */
export function convertToPassengerListFormat(selectedPaxData) {
  return selectedPaxData
    .filter(p => !p.isAssisted) // Ne restaurer que les non-assistés
    .map(p => ({
      id: `passenger-${Date.now()}-${Math.random().toString(36).substr(2, 9)}`,
      selectedUuid: p.uuid,
      idPax: p.idPax,
      lastName: p.lastName,
      firstName: p.firstName,
      flightNumber: p.flightNumber,
      departureTime: p.departureTime,
      goLieu: p.goLieu,
      goAcc: p.goAcc,
      ssr1: p.ssr1,
      status: p.ssr1 || 'WCHR',
      isSkyPriority: p.isSkyPriority,
      isAgentEnRouteActive: false,
      isAssisted: false,
      airline: '',
      destination: '',
      addedAt: new Date(p.created_at).toLocaleTimeString('fr-FR', { hour: '2-digit', minute: '2-digit' }),
    }));
}